/*
 * Cross-feature compatibility classes for the current Public Web.
 *
 * New Website 4.3 UI should prefer its owning CSS Module/feature stylesheet.
 * Do not add one-off visual fixes here; this file exists only for class names
 * that are still shared by multiple reachable runtime surfaces.
 */
@layer components {
  .glass-card {
    @apply relative overflow-hidden rounded-2xl;
    background: rgba(74, 58, 58, 0.6);
    backdrop-filter: blur(24px) saturate(180%);
    -webkit-backdrop-filter: blur(24px) saturate(180%);
    border: 1px solid rgba(255,255,255,0.1);
    box-shadow: 0 8px 32px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.1);
  }

  .glass-card::before {
    content: '';
    @apply absolute inset-0 pointer-events-none;
    background: linear-gradient(135deg,
      rgba(255,255,255,0.2) 0%, rgba(255,255,255,0.08) 30%, transparent 60%
    );
    border-radius: inherit;
  }

  .glass-card::after {
    content: '';
    @apply absolute inset-0 pointer-events-none rounded-2xl;
    background: radial-gradient(ellipse at 50% 0%, rgba(255,255,255,0.15) 0%, transparent 50%);
  }

  .glass-button {
    @apply relative min-h-11 overflow-hidden rounded-full px-5 py-3 md:px-8 md:py-4 font-semibold;
    transition-property: transform, box-shadow, border-color, background-color, color;
    transition-duration: 300ms;
    background: linear-gradient(135deg,
      rgba(255,255,255,0.15) 0%, rgba(255,255,255,0.08) 50%, rgba(255,255,255,0.05) 100%
    );
    backdrop-filter: blur(16px) saturate(180%);
    -webkit-backdrop-filter: blur(16px) saturate(180%);
    border: 1px solid rgba(255,255,255,0.2);
    box-shadow: 0 4px 20px rgba(0,0,0,0.15), inset 0 1px 1px rgba(255,255,255,0.2);
  }

  .glass-button:hover {
    box-shadow: 0 5px 22px rgba(0,0,0,0.2), inset 0 1px 1px rgba(255,255,255,0.3);
    border-color: rgba(255,255,255,0.3);
  }

  .glass-button-sm {
    @apply relative min-h-11 overflow-hidden rounded-full px-4 py-2 font-semibold;
    transition-property: transform, box-shadow, border-color, background-color, color;
    transition-duration: 300ms;
    background: linear-gradient(135deg,
      rgba(255,255,255,0.15) 0%, rgba(255,255,255,0.08) 50%, rgba(255,255,255,0.05) 100%
    );
    backdrop-filter: blur(16px) saturate(180%);
    -webkit-backdrop-filter: blur(16px) saturate(180%);
    border: 1px solid rgba(255,255,255,0.2);
    box-shadow: 0 4px 20px rgba(0,0,0,0.15), inset 0 1px 1px rgba(255,255,255,0.2);
  }

  .glass-button-sm:hover {
    box-shadow: 0 5px 22px rgba(0,0,0,0.2), inset 0 1px 1px rgba(255,255,255,0.3);
    border-color: rgba(255,255,255,0.3);
  }

  .gold-button {
    @apply relative min-h-11 overflow-hidden rounded-full px-5 py-3 md:px-8 md:py-4 font-semibold;
    transition-property: transform, box-shadow, background-position, background-color, color;
    transition-duration: 300ms;
    color: hsl(var(--primary-foreground));
    background: linear-gradient(135deg,
      hsl(45,60%,70%) 0%, hsl(45,70%,78%) 50%, hsl(45,60%,70%) 100%
    );
    background-size: 200% 200%;
    box-shadow: 0 4px 18px rgba(220,190,130,0.24), inset 0 1px 0 rgba(255,255,255,0.45);
  }

  .gold-button:hover {
    background-position: 100% 100%;
    box-shadow: 0 5px 20px rgba(220,190,130,0.28), inset 0 1px 0 rgba(255,255,255,0.5);
    cursor: pointer;
  }

  .gold-button:active {
    transform: translateY(-1px) scale(0.99);
  }

  .gold-button:focus-visible {
    outline: 2px solid hsl(var(--primary));
    outline-offset: 3px;
  }

  .text-gold-gradient {
    color: #e0c985;
  }

  .section-divider {
    @apply w-20 h-1 mx-auto rounded-full;
    background: linear-gradient(90deg, transparent, hsl(42,50%,55%), transparent);
  }

  .hero-dark-overlay {
    background: linear-gradient(
      180deg,
      rgba(10, 12, 18, 0.55) 0%,
      rgba(10, 12, 18, 0.65) 50%,
      rgba(10, 12, 18, 0.70) 100%
    );
  }

  .hero-gold-accent {
    background:
      radial-gradient(ellipse at 30% 20%, rgba(220, 190, 130, 0.08) 0%, transparent 50%),
      radial-gradient(ellipse at 70% 80%, rgba(220, 190, 130, 0.05) 0%, transparent 50%);
  }

  .hero-grid-pattern {
    background-image: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.3) 1px, transparent 0);
    background-size: 40px 40px;
  }

  .scroll-indicator {
    @apply absolute bottom-8 left-1/2 -translate-x-1/2;
    animation: none;
  }
}

